package com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.application.service;
import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.infrastructure.persistence.BusinessSequenceJdbcRepository; import org.springframework.stereotype.Service; import java.util.Map;
@Service public class BusinessSequenceService { private final BusinessSequenceJdbcRepository repo; private static final Map<String,String> PREFIXES=Map.of("department","DEP","position","CAR","employee","EMP","employment_contract","CON","employee_file","EXP","work_shift","TUR","employee_incident","INC"); public BusinessSequenceService(BusinessSequenceJdbcRepository r){repo=r;} public String nextCode(String key){String prefix=PREFIXES.get(key); if(prefix==null) throw new IllegalArgumentException("Clave de secuencia no válida"); return prefix+"-"+String.format("%06d",repo.nextValue(key));} }
